// Copy the TypeScript declaration files generated by @asciidoctor/core into
// this package's `types` directory, as is done when a release is performed
// (see tasks/publish.js at the root of the repository).
import { cp } from 'node:fs/promises'
import { join } from 'node:path'

const packageDirectory = join(import.meta.dirname, '..')
await cp(
  join(packageDirectory, '..', 'core', 'types'),
  join(packageDirectory, 'types'),
  { recursive: true }
)
